import { test, expect } from "../helpers/system-control-browser";

for (const theme of ["light", "dark"] as const) {
  test(`landing: mobile polish ${theme}`, async ({ page }, info) => {
    test.skip(info.project.name !== "desktop", "Own viewport matrix");
    await page.emulateMedia({ reducedMotion: "reduce" });
    await page.addInitScript(
      (theme) => localStorage.setItem("mailloop-theme", theme),
      theme,
    );
    await page.goto("/");
    await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
    await page.evaluate(() => document.fonts.ready);
    for (const width of [320, 375, 390, 639, 640, 768, 1440]) {
      await page.setViewportSize({ width, height: 900 });
      await page.evaluate(
        () =>
          new Promise<void>((resolve) =>
            requestAnimationFrame(() => requestAnimationFrame(() => resolve())),
          ),
      );
      await expect(page.locator(".landing-dashboard-perspective")).toBeVisible({
        visible: width >= 640,
      });
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
      const columns = await page
        .locator("#features article")
        .evaluateAll(
          (cards) =>
            new Set(
              cards.map((card) =>
                Math.round(card.getBoundingClientRect().left),
              ),
            ).size,
        );
      expect(columns).toBe(width < 640 ? 1 : width <= 860 ? 2 : 3);
      const cta = page.locator(".landing-hero-cta");
      const bounds = await cta.boundingBox();
      expect(bounds!.x).toBeGreaterThanOrEqual(20);
      expect(bounds!.x + bounds!.width).toBeLessThanOrEqual(width - 19);
      if (width < 640) {
        const layout = await page.evaluate(() => {
          const rect = (selector: string) =>
            document.querySelector(selector)!.getBoundingClientRect();
          return {
            heroEnd: rect(".landing-hero").bottom,
            highlightsEnd: rect(".landing-hero-highlights").bottom,
            howStart: rect("#how .lower-eyebrow").top,
            heroLeft: rect(".landing-hero").left,
            howLeft: rect("#how").left,
            pricingLeft: rect(".pricing-content").left,
          };
        });
        expect(layout.heroEnd - layout.highlightsEnd).toBeLessThanOrEqual(25);
        expect(layout.howStart - layout.highlightsEnd).toBeLessThanOrEqual(80);
        expect(layout.howLeft).toBe(layout.heroLeft);
        expect(layout.pricingLeft).toBe(layout.heroLeft);
      }
      await page.screenshot({
        path: info.outputPath(`${theme}-${width}.png`),
        fullPage: true,
      });
    }
  });
}
